const item = $input.first().json.body || $input.first().json;

const type = item.type || 'DISPUTE'; // 'DISPUTE' | 'CONTENT_MODERATION' | 'RAIN_RULE'
const matchId = item.matchId;
const tournamentName = item.tournamentName || 'Mana Community Championship';
const incidentDescription = item.incidentDescription || item.text || '';
const involvedParties = item.parties || item.playerName || 'Team A vs Team B';

const prompt = `You are the Chief Disciplinary Officer & Head Arbitrator for the Mana Community Sports Council.
Analyze the following incident or user submission for disputes, toxicity, unsportsmanlike conduct, or rule violations.

Context:
- Incident Type: ${type}
- Tournament: ${tournamentName}
- Involved Parties: ${JSON.stringify(involvedParties)}
- Description / User Content: "${incidentDescription}"

Rules & Standards:
1. Zero tolerance for abusive language, threats, defamation, or discrimination.
2. In sports disputes (walkovers, rain stops, contested calls), apply standard fair-play regulations.
3. Walkover Rule: A team failing to report within 15 minutes of scheduled time forfeits the match.
4. Rain Delay: Recommend proportionate overs reduction or reschedule if less than 50% overs possible.

Respond ONLY with a valid JSON object matching this schema:
{
  "actionTaken": "DISMISSED" | "SANCTION_APPLIED" | "WALKOVER_CONFIRMED" | "TARGET_REVISED" | "CONTENT_CENSORED" | "REFERRED_TO_COMMITTEE",
  "toxicityScore": number (0.0 to 1.0),
  "isHostile": boolean,
  "officialRuling": "Clear, authoritative 2-paragraph verdict explaining the decision",
  "penaltyDetails": {
    "warningIssued": boolean,
    "pointsDeducted": number,
    "matchForfeitTo": string | null,
    "suspensionPeriod": string | null
  },
  "revisedMatchConditions": {
    "oversReducedTo": number | null,
    "revisedTargetRuns": number | null,
    "rescheduledDate": string | null
  },
  "residentMessage": "Neutral, de-escalating communication message to be sent to both parties via app"
}`;

return [{
  json: {
    type,
    matchId,
    incidentDescription,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsedRuling = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsedRuling = JSON.parse(rawText);
} catch (err) {
  parsedRuling = {
    actionTaken: "REFERRED_TO_COMMITTEE",
    toxicityScore: 0.1,
    isHostile: false,
    officialRuling: "Incident noted and referred to committee review.",
    penaltyDetails: { warningIssued: false, pointsDeducted: 0, matchForfeitTo: null, suspensionPeriod: null },
    revisedMatchConditions: { oversReducedTo: null, revisedTargetRuns: null, rescheduledDate: null },
    residentMessage: "Your report has been logged with the sports committee for review."
  };
}

const meta = $('Prepare Arbitration Prompt').first().json;

return [{
  json: {
    status: "success",
    matchId: meta.matchId,
    incidentType: meta.type,
    arbitratedAt: new Date().toISOString(),
    ruling: parsedRuling
  }
}];
